allc = [c for r in rows for s in r['sub_claims'] for c in s['citations']]
nsub = sum(len(r['sub_claims']) for r in rows)
orhits = sum(1 for c in allc if c['source_id'] in ('OR-27-1', 'OR-27-2', 'OR-27-3'))
filled = sum(1 for c in allc if str(c.get('page_basis', '')).startswith('printed number from the archive.org page-by-page OCR'))
rem = collections.Counter(c['source_id'] for c in allc if c.get('printed_page') in (None, '') and not c['source_id'].startswith(('OR-', 'NPS', 'CA:', 'GBG', 'ADAMS', 'WEB-F-300', 'WEB-F-322', 'WEB-F-325', 'WEB-F-332', 'WEB-F-339')))
nrem = sum(rem.values())
remtxt = ', '.join('%d of %s' % (v, k) for k, v in sorted(rem.items(), key=lambda x: -x[1]))
def short(r, n=230):
    t = r['corrected_claim']
    return (t if len(t) <= n else t[:n].rsplit(' ', 1)[0] + ' ...').replace('|', '/')

# numbers used by the wave-6 items
_wn = [json.loads(l) for l in open(os.path.join(G, 'evidence_corrections/web-nps-landscape.jsonl'), encoding='utf-8') if l.strip()]
_ids = set(r['id'] for r in rows)
web_nps_n = sum(1 for x in _wn if x.get('id') in _ids); web_nps_agg = sum(1 for x in _wn if x.get('id') == 'R14.0000')
