nps_n = len(_man); habs_n = sum(1 for k in _man if k.startswith('NPS-HABS-'))
sem_n = sum(1 for k in json.load(open(os.path.join(ROOT, 'tmp/fence-1/dl/sem/provenance.json')))['files'] if k.endswith('.pdf')) + 1 - 1
lines = []
